 [Serializable] public class RobotProject {public string format="ashina-robot-studio",name="Yeni takım robotu",season="2025",quality="high",tagLayout="welded";public int version=2,team=10576;public TrainingData training=new TrainingData();public DriveData drive=new DriveData();public List<RobotPart> parts=new List<RobotPart>();public List<RobotAction> actions=new List<RobotAction>();public List<CameraData> cameras=new List<CameraData>();public Dictionary<string,ModelAsset> assets=new Dictionary<string,ModelAsset>();public double[] initialPose={2,4,0};public Dictionary<string,int> inventory=new Dictionary<string,int>{{"ball",0},{"coral",0},{"note",0},{"algae",0},{"fuel",0}};public NetworkData network=new NetworkData();public JObject blocklyProject;public static RobotProject Empty(){var p=new RobotProject{season="2026"};p.parts.Add(new RobotPart{id="chassis",name="Ana şase",parent=null,size=new[]{.8,.7,.15},position=new[]{0.0,0.0,.2}});return p;}}
 public static class ProjectIO {
  public static readonly JsonSerializerSettings Settings=new JsonSerializerSettings{TypeNameHandling=TypeNameHandling.None,MaxDepth=96,MissingMemberHandling=MissingMemberHandling.Ignore};
  public static RobotProject Parse(string text){if(text==null||text.Length>200000000)throw new Exception("Proje dosyası çok büyük.");var p=JsonConvert.DeserializeObject<RobotProject>(text,Settings);Validate(p);return p;}
  public static string Write(RobotProject p)=>JsonConvert.SerializeObject(p,Formatting.Indented,Settings);
  public static void Validate(RobotProject p){
   if(p==null||p.format!="ashina-robot-studio"||p.version!=2)throw new Exception("Robot Studio 0.2 proje biçimi gerekli.");if(string.IsNullOrWhiteSpace(p.name)||p.name.Length>160||p.team<1||p.team>99999)throw new Exception("Robot / takım adı geçersiz.");if(!new[]{"practice","2024","2025","2026"}.Contains(p.season))throw new Exception("Sezon geçersiz.");
   if(p.parts==null||p.parts.Count>128||!p.parts.Any(x=>x.id=="chassis"))throw new Exception("Robot parça listesi geçersiz.");var ids=new HashSet<string>();foreach(var a in p.parts){if(a==null||string.IsNullOrEmpty(a.id)||!ids.Add(a.id)||!new[]{"box","cylinder","asset","group"}.Contains(a.kind)||a.name==null||a.name.Length>100)throw new Exception("Parça kaydı geçersiz.");V(a.position);V(a.rotation,-36000,36000);V(a.pivot);V(a.size,.001,30);N(a.scale,.00001,1000);if(a.assetCenter!=null)V(a.assetCenter);}
   foreach(var a in p.parts){var visited=new HashSet<string>{a.id};var parent=a.parent;while(parent!=null){if(!ids.Contains(parent)||!visited.Add(parent))throw new Exception("Parça bağlantısında döngü veya eksik üst parça var.");parent=p.parts.Find(x=>x.id==parent).parent;}}
   if(p.actions==null||p.actions.Count>200)throw new Exception("En fazla 200 eylem kullanılabilir.");var actionIds=new HashSet<string>();foreach(var a in p.actions){if(a==null||!actionIds.Add(a.id)||!ids.Contains(a.partId)||!new[]{"move","emit","capture"}.Contains(a.type)||!new[]{"hold","press","toggle"}.Contains(a.mode)||!PieceCatalog.Names.ContainsKey(a.piece)||a.name==null||a.name.Length>160||a.controller<0||a.controller>5)throw new Exception("Eylem kaydı geçersiz.");V(a.from.position);V(a.to.position);V(a.from.rotation,-36000,36000);V(a.to.rotation,-36000,36000);V(a.spawn,-10,10);N(a.duration,.05,120);N(a.speed,0,40);N(a.pitch,-90,90);N(a.yaw,-180,180);N(a.interval,.05,10);N(a.captureRadius,.05,3);}
   if(p.cameras==null||p.cameras.Count>16)throw new Exception("Kamera sayısı geçersiz.");var cameraIds=new HashSet<string>();var names=new HashSet<string>();foreach(var c in p.cameras){if(c==null||!ids.Contains(c.parent)||!cameraIds.Add(c.id)||!names.Add(c.name)||!System.Text.RegularExpressions.Regex.IsMatch(c.name,@"^[A-Za-z][\w-]{0,63}$"))throw new Exception("Kamera adı veya bağlantısı geçersiz.");V(c.position);V(c.rotation,-36000,36000);N(c.hfov,5,170);N(c.vfov,5,170);N(c.range,.1,50);N(c.latency,0,1000);}
   if(p.assets==null)throw new Exception("Model listesi yok.");long length=0;foreach(var a in p.assets.Values){if(a==null||a.data==null||!new[]{"stl","glb","obj"}.Contains(a.type))throw new Exception("Model dosyası geçersiz.");length+=a.data.Length;}if(length>180000000)throw new Exception("Model dosyalarının toplam boyutu çok büyük.");foreach(var a in p.parts)if(a.kind=="asset"&&(a.asset==null||!p.assets.ContainsKey(a.asset)))throw new Exception("Parça model dosyası eksik.");
   if(!new[]{"welded","andymark"}.Contains(p.tagLayout))throw new Exception("AprilTag yerleşimi geçersiz.");if(p.training==null||p.training.capacity<1||p.training.capacity>1000||p.training.fuelCount<0||p.training.fuelCount>504)throw new Exception("Antrenman ayarı geçersiz.");foreach(var action in p.actions){N(action.captureEfficiency,0,1);V(action.captureSize,.01,5);if(!new[]{"box","sphere"}.Contains(action.captureShape))throw new Exception("Toplama bölgesi geçersiz.");N(action.speedScale,-1000,1000);N(action.speedOffset,-1000,1000);N(action.coralSpin,-1440,1440);N(action.piecePitch,-180,180);N(action.pieceYaw,-180,180);N(action.pieceRoll,-180,180);if(!new[]{"auto","custom"}.Contains(action.orientationMode))throw new Exception("Eşya çıkış duruşu geçersiz.");}
   if(p.drive==null||!new[]{"swerve","differential","mecanum"}.Contains(p.drive.type))throw new Exception("Sürüş türü geçersiz.");N(p.drive.maxSpeed,.1,15);N(p.drive.acceleration,.1,40);N(p.drive.turnRate,.1,15);V(p.drive.dimensions,.05,5);V(p.initialPose);if(p.network==null||p.network.port<1||p.network.port>65535||!new[]{"observe","physics"}.Contains(p.network.mode)||!System.Text.RegularExpressions.Regex.IsMatch(p.network.host,@"^[\w.:-]{1,253}$"))throw new Exception("NetworkTables adresi geçersiz.");ValidateNetworkExtras(p);
  }
  public static void ValidateNetworkExtras(RobotProject p){
   if(!new[]{"auto","radians","degrees","field2d","botpose"}.Contains(p.network.poseFormat))throw new Exception("NT konum biçimi geçersiz.");
   foreach(var a in p.actions){if(!new[]{"trigger","position"}.Contains(a.ntMode)||a.ntField==null||a.ntField.Length>256||a.topic==null||a.topic.Length>1000)throw new Exception("NT eylem eşlemesi geçersiz.");N(a.ntMin,-1000000,1000000);N(a.ntMax,-1000000,1000000);if(a.ntMode=="position"&&Math.Abs(a.ntMax-a.ntMin)<1e-9)throw new Exception("NT başlangıç ve bitiş değerleri farklı olmalı.");}
  }
  static void N(double n,double min,double max){if(double.IsNaN(n)||double.IsInfinity(n)||n<min||n>max)throw new Exception("Sayısal ayar sınır dışında.");}static void V(double[] v,double min=-1000,double max=1000){if(v==null||v.Length!=3)throw new Exception("Üç eksenli değer gerekli.");foreach(var n in v)N(n,min,max);}
 }
 public static class Frc {
  public static Vector3 Position(double[] v)=>new Vector3((float)-v[1],(float)v[2],(float)v[0]);
  public static double[] Position(Vector3 v)=>new double[]{v.z,-v.x,v.y};
  public static Quaternion Rotation(double[] degrees){double x=degrees[0]*Math.PI/360,y=degrees[1]*Math.PI/360,z=degrees[2]*Math.PI/360,sx=Math.Sin(x),cx=Math.Cos(x),sy=Math.Sin(y),cy=Math.Cos(y),sz=Math.Sin(z),cz=Math.Cos(z);return QuaternionData(sx*cy*cz+cx*sy*sz,cx*sy*cz-sx*cy*sz,cx*cy*sz+sx*sy*cz,cx*cy*cz-sx*sy*sz);}
  public static Quaternion QuaternionData(double x,double y,double z,double w)=>new Quaternion((float)y,(float)-z,(float)-x,(float)w);
  public static double[] Euler(Quaternion q){double x=-q.z,y=q.x,z=-q.y,w=q.w,m11=1-2*(y*y+z*z),m12=2*(x*y-z*w),m13=2*(x*z+y*w),m23=2*(y*z-x*w),m33=1-2*(x*x+y*y),m32=2*(y*z+x*w),m22=1-2*(x*x+z*z);double ey=Math.Asin(Math.Max(-1,Math.Min(1,m13))),ex,ez;if(Math.Abs(m13)<.9999999){ex=Math.Atan2(-m23,m33);ez=Math.Atan2(-m12,m11);}else{ex=Math.Atan2(m32,m22);ez=0;}return new[]{ex*180/Math.PI,ey*180/Math.PI,ez*180/Math.PI};}
  public static Vector3 Direction(double pitch,double yaw)=>Position(new[]{Math.Cos(pitch*Math.PI/180)*Math.Cos(yaw*Math.PI/180),Math.Cos(pitch*Math.PI/180)*Math.Sin(yaw*Math.PI/180),Math.Sin(pitch*Math.PI/180)});
 }
